#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <grpc/grpc.h>
#include <grpc/support/log.h>
#include "comment_service.grpc.pb.h"
#include "auth_client.h"
#include "html_sanitizer.h"
#include "db_store.h"

#define MAX_COMMENT_LEN 4096
#define SERVICE_TOKEN_HEADER "x-service-auth-token"
#define RENDER_MODE_PLAINTEXT 0
#define RENDER_MODE_RICHTEXT 1

typedef struct {
    char author[256];
    char body[MAX_COMMENT_LEN];
    int render_mode;
    int is_service_call;
    char service_origin[128];
} CommentRequest;

typedef struct {
    char sanitized_body[MAX_COMMENT_LEN];
    int needs_html_escape;
    int actual_render_mode;
} SanitizedComment;

/* Validates the cross-service authentication token */
static int validate_service_token(const char *token, char *origin_out) {
    if (!token || strlen(token) < 16) return 0;
    /* Verify HMAC-SHA256 signature with shared secret */
    int valid = auth_client_verify_service_token(token);
    if (valid && origin_out) {
        auth_client_extract_origin(token, origin_out, 128);
    }
    return valid;
}

/* Multi-pass sanitization for rich text comments */
static int sanitize_richtext(const char *input, char *output, size_t out_len) {
    /* Pass 1: Strip dangerous tags (script, iframe, object, embed) */
    char intermediate[MAX_COMMENT_LEN];
    html_strip_dangerous_tags(input, intermediate, sizeof(intermediate));

    /* Pass 2: Normalize Unicode to NFC to prevent bypass via decomposition */
    char normalized[MAX_COMMENT_LEN];
    unicode_normalize_nfc(intermediate, normalized, sizeof(normalized));

    /* Pass 3: Whitelist allowed tags and attributes */
    int result = html_whitelist_filter(normalized, output, out_len);
    return result;
}

/* Determines if comment needs HTML escaping based on context */
static int compute_escape_requirement(const CommentRequest *req) {
    /* Service-to-service calls from the rich-text editor service
       are pre-sanitized at the editor layer, so they use a
       different pipeline that preserves formatting */
    if (req->is_service_call && req->render_mode == RENDER_MODE_RICHTEXT) {
        /* Trusted service origin - editor already sanitized */
        if (strcmp(req->service_origin, "richtext-editor-svc") == 0) {
            return 0; /* No additional escaping needed */
        }
    }
    /* For richtext from end users, sanitize but preserve allowed HTML */
    if (req->render_mode == RENDER_MODE_RICHTEXT) {
        return 0; /* Will go through sanitize_richtext instead */
    }
    return 1; /* Plaintext always gets escaped */
}

/* Process and store a comment */
static int process_comment(CommentRequest *req, SanitizedComment *out) {
    memset(out, 0, sizeof(SanitizedComment));
    out->needs_html_escape = compute_escape_requirement(req);

    if (out->needs_html_escape) {
        /* Full HTML entity encoding for plaintext */
        html_entity_encode(req->body, out->sanitized_body, MAX_COMMENT_LEN);
        out->actual_render_mode = RENDER_MODE_PLAINTEXT;
    } else if (req->is_service_call && 
               strcmp(req->service_origin, "richtext-editor-svc") == 0) {
        /* Trusted pre-sanitized content from editor service */
        strncpy(out->sanitized_body, req->body, MAX_COMMENT_LEN - 1);
        out->actual_render_mode = RENDER_MODE_RICHTEXT;
    } else {
        /* User-submitted richtext: run through sanitizer */
        int san_ok = sanitize_richtext(req->body, out->sanitized_body, MAX_COMMENT_LEN);
        if (san_ok != 0) {
            /* Sanitization failed: do NOT store as richtext with
               possibly-unsafe content. Fall back to safe plaintext
               so the stored render mode always matches the actual
               sanitization applied. */
            memset(out->sanitized_body, 0, MAX_COMMENT_LEN);
            html_entity_encode(req->body, out->sanitized_body, MAX_COMMENT_LEN);
            out->needs_html_escape = 1;
            out->actual_render_mode = RENDER_MODE_PLAINTEXT;
        } else {
            out->actual_render_mode = RENDER_MODE_RICHTEXT;
        }
    }
    return 0;
}

/* gRPC handler for PostComment RPC */
void handle_post_comment(grpc_call *call, const PostCommentProto *proto) {
    CommentRequest req;
    memset(&req, 0, sizeof(req));

    strncpy(req.author, proto->author, sizeof(req.author) - 1);
    strncpy(req.body, proto->body, sizeof(req.body) - 1);
    req.render_mode = proto->render_mode;

    /* Check for service-to-service authentication */
    const char *svc_token = grpc_call_get_metadata(call, SERVICE_TOKEN_HEADER);
    if (svc_token) {
        char origin[128] = {0};
        if (validate_service_token(svc_token, origin)) {
            req.is_service_call = 1;
            strncpy(req.service_origin, origin, sizeof(req.service_origin) - 1);
        }
    }

    SanitizedComment result;
    process_comment(&req, &result);

    /* Store with the ACTUAL render mode determined by processing,
       not the raw request render_mode */
    db_store_comment(req.author, result.sanitized_body, result.actual_render_mode);

    grpc_send_response(call, GRPC_STATUS_OK, "Comment posted");
}

/* gRPC handler for GetComments RPC - serves to web frontend */
void handle_get_comments(grpc_call *call, const GetCommentsProto *proto) {
    CommentRecord records[50];
    int count = db_get_comments(proto->thread_id, records, 50);
    if (count < 0) count = 0;
    if (count > 50) count = 50;

    GetCommentsResponse resp;
    resp.count = count;
    for (int i = 0; i < count; i++) {
        resp.comments[i].author = records[i].author;
        resp.comments[i].body = records[i].body;
        /* Frontend uses this to decide: innerHTML vs textContent */
        resp.comments[i].is_richtext = (records[i].render_mode == RENDER_MODE_RICHTEXT);
    }
    grpc_send_response_proto(call, &resp);
}
